        if (!settled && hasListener) {
          signal.removeEventListener('abort', abortHandler);
          hasListener = false;
          settled = true;
        }
        resolve(result);
      })
      .catch(error => {
        if (!settled && hasListener) {
          signal.removeEventListener('abort', abortHandler);
          hasListener = false;
          settled = true;
        }
        reject(error);
      });
  });

  return returnedPromise;
